import sqlite3
import json

DB_PATH = r'd:\web project\multi app downloader\backend\appstore.db'
JSON_PATH = r'd:\web project\multi app downloader\frontend\mock\apps.json'
APP_NAME = "Google Drive"
NEW_URL = "data:image/jpeg;base64,"

# Update DB
conn = sqlite3.connect(DB_PATH)
cursor = conn.cursor()
cursor.execute("UPDATE app SET iconPlaceholder = ? WHERE name = ?", (NEW_URL, APP_NAME))
conn.commit()
conn.close()

# Update JSON
with open(JSON_PATH, 'r', encoding='utf-8') as f:
    apps = json.load(f)

for app in apps:
    if app['name'] == APP_NAME:
        app['iconPlaceholder'] = NEW_URL
        
with open(JSON_PATH, 'w', encoding='utf-8') as f:
    json.dump(apps, f, indent=2, ensure_ascii=False)
    
print("Updated Google Drive logo!")
